(function(){
  if(window.Splide){return;}
  function Splide(selector,options){
    this.root=document.querySelector(selector);
    this.options=options||{};
    this.index=0;
    this.perPage=this.options.perPage||3;
    this.breakpoints=this.options.breakpoints||{};
  }
  Splide.prototype._calcPerPage=function(){
    var width=window.innerWidth||1200;
    var per=this.options.perPage||3;
    Object.keys(this.breakpoints).forEach(function(bp){
      if(width<=Number(bp) && this.breakpoints[bp].perPage){ per=this.breakpoints[bp].perPage; }
    },this);
    this.perPage=per;
  };
  Splide.prototype._renderUI=function(){
    var self=this;
    var track=this.root.querySelector('.splide__track');
    var list=this.root.querySelector('.splide__list');
    if(!track||!list){return;}
    this.slides=[].slice.call(list.children);
    this._calcPerPage();
    list.style.display='flex';
    list.style.transition='transform .45s ease';
    list.style.willChange='transform';
    this.slides.forEach(function(slide){
      slide.style.flex='0 0 '+(100/self.perPage)+'%';
      slide.style.maxWidth=(100/self.perPage)+'%';
    });

    var prev=document.createElement('button');
    prev.className='splide__arrow splide__arrow--prev';
    prev.type='button';
    prev.setAttribute('aria-label','Previous');
    prev.innerHTML='‹';
    var next=document.createElement('button');
    next.className='splide__arrow splide__arrow--next';
    next.type='button';
    next.setAttribute('aria-label','Next');
    next.innerHTML='›';
    this.root.appendChild(prev);this.root.appendChild(next);

    var pag=document.createElement('ul'); pag.className='splide__pagination';
    this.pages=Math.max(1,Math.ceil(this.slides.length/this.perPage));
    for(var i=0;i<this.pages;i++){
      var li=document.createElement('li');
      var btn=document.createElement('button');
      btn.type='button'; btn.className='splide__pagination__page'+(i===0?' is-active':'');
      (function(idx){btn.addEventListener('click',function(){self.go(idx);});})(i);
      li.appendChild(btn); pag.appendChild(li);
    }
    this.root.appendChild(pag);

    prev.addEventListener('click',function(){self.go(self.index-1);});
    next.addEventListener('click',function(){self.go(self.index+1);});
    window.addEventListener('resize',function(){
      self._calcPerPage();
      self.pages=Math.max(1,Math.ceil(self.slides.length/self.perPage));
      self.slides.forEach(function(slide){slide.style.flex='0 0 '+(100/self.perPage)+'%';slide.style.maxWidth=(100/self.perPage)+'%';});
      if(self.index>self.pages-1){self.index=self.pages-1;}
      self._update();
    });
    this._update();
  };
  Splide.prototype._update=function(){
    var list=this.root.querySelector('.splide__list');
    if(!list){return;}
    list.style.transform='translateX(-'+(this.index*100)+'%)';
    var bullets=this.root.querySelectorAll('.splide__pagination__page');
    bullets.forEach(function(b,i){b.classList.toggle('is-active',i===this.index);},this);
  };
  Splide.prototype.go=function(index){
    if(this.pages<=1){this.index=0;this._update();return;}
    if(index<0){index=this.pages-1;}
    if(index>this.pages-1){index=0;}
    this.index=index;this._update();
  };
  Splide.prototype.mount=function(){ if(!this.root){return this;} this._renderUI(); return this; };
  window.Splide=Splide;
})();
